class TokenVerifier:
    """Verifies API request signatures using HMAC-SHA256.

    Token format: base64(user_id:timestamp:signature)
    Signature = HMAC-SHA256(secret, user_id + ':' + timestamp + ':' + nonce)
    """

    def __init__(self, secret_key):
        self.secret_key = secret_key
        self._nonce_cache = set()

    def generate_token(self, user_id, nonce=None):
        timestamp = str(int(time.time()))
        if nonce is None:
            nonce = os.urandom(16).hex()
        payload = f"{user_id}:{timestamp}:{nonce}"
        sig = self._compute_signature(payload)
        return f"{payload}:{sig}"

    def _compute_signature(self, payload):
        return hmac.new(self.secret_key, payload.encode(), hashlib.sha256).hexdigest()

    def verify_token(self, token):
        """Verify token and return (user_id, is_valid) tuple."""
        try:
            parts = token.rsplit(':', 1)
            if len(parts) != 2:
                return None, False
            payload, provided_sig = parts

            # Verify signature
            expected_sig = self._compute_signature(payload)
            if not self._safe_compare(expected_sig, provided_sig):
                return None, False

            # Parse payload
            payload_parts = payload.split(':')
            if len(payload_parts) != 3:
                return None, False

            user_id_str, timestamp_str, nonce = payload_parts

            # Check timestamp freshness (5 minute window)
            token_time = int(timestamp_str)
            current_time = int(time.time())
            if abs(current_time - token_time) > 300:
                return None, False

            # Check nonce reuse
            if nonce in self._nonce_cache:
                return None, False
            self._nonce_cache.add(nonce)

            return int(user_id_str), True

        except (ValueError, TypeError):
            return None, False

    def _safe_compare(self, a, b):
        """Constant-time comparison to prevent timing attacks."""
        return hmac.compare_digest(a, b)


class AccessController:
    """Role-based access control for document retrieval."""

    ROLE_HIERARCHY = {
        'admin': 3,
        'manager': 2, 
        'user': 1,
        'guest': 0
    }

    CLASSIFICATION_LEVELS = {
        'public': 0,
        'internal': 1,
        'confidential': 2,
        'classified': 3
    }

    def can_access_document(self, user_role, document_classification):
        """Check if user role has sufficient clearance for document classification."""
        role_level = self.ROLE_HIERARCHY.get(user_role, 0)
        doc_level = self.CLASSIFICATION_LEVELS.get(document_classification, 3)
        return role_level >= doc_level

    def get_accessible_documents(self, db, user_id, user_role, offset, limit):
        """Retrieve documents accessible to the user with pagination."""
        # Determine maximum classification level for this role
        max_level = self.ROLE_HIERARCHY.get(user_role, 0)

        # Build classification filter
        accessible_classifications = [
            cls for cls, level in self.CLASSIFICATION_LEVELS.items()
            if level <= max_level
        ]

        if not accessible_classifications:
            return []

        # Validate pagination parameters
        safe_offset, safe_limit = self._sanitize_pagination(offset, limit)

        placeholders = ','.join(['?' for _ in accessible_classifications])
        query = f"SELECT id, title, classification FROM documents WHERE classification IN ({placeholders}) LIMIT ? OFFSET ?"
        params = accessible_classifications + [safe_limit, safe_offset]

        cursor = db.execute(query, params)
        return [dict(row) for row in cursor.fetchall()]

    def _sanitize_pagination(self, offset, limit):
        """Sanitize pagination parameters to prevent abuse."""
        # Convert to integers, handling potential string inputs
        try:
            offset_int = int(offset)
            limit_int = int(limit)
        except (ValueError, TypeError):
            return 0, 20

        # Ensure offset is non-negative
        if offset_int < 0:
            safe_offset = 0
        else:
            safe_offset = offset_int

        # Cap limit between 1 and 100
        safe_limit = max(1, min(limit_int, 100))

        return safe_offset, safe_limit


class DocumentService:
    """Service layer for document operations."""

    def __init__(self):
        self.access_controller = AccessController()

    def list_documents(self, db, user_id, user_role, page=1, per_page=20):
        """List documents with pagination, respecting access controls."""
        # Validate page is positive
        if page < 1:
            page = 1
        if per_page < 1:
            per_page = 20
        offset = (page - 1) * per_page
        return self.access_controller.get_accessible_documents(
            db, user_id, user_role, offset, per_page
        )

    def get_document(self, db, user_id, user_role, doc_id):
        """Get a specific document if user has access."""
        cursor = db.execute(
            "SELECT * FROM documents WHERE id = ?", (doc_id,)
        )
        doc = cursor.fetchone()
        if doc is None:
            return None, "not_found"

        if not self.access_controller.can_access_document(
            user_role, doc['classification']
        ):
            return None, "forbidden"

        return dict(doc), None


# Initialize components
token_verifier = TokenVerifier(app.config['SECRET_KEY'])
doc_service = DocumentService()

def require_auth(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        token = request.headers.get('X-API-Token')
        if not token:
            abort(401)

        user_id, valid = token_verifier.verify_token(token)
        if not valid:
            abort(401)

        db = get_db()
        user = db.execute(
            "SELECT * FROM users WHERE id = ?", (user_id,)
        ).fetchone()

        if user is None:
            db.close()
            abort(401)

        request.current_user = dict(user)
        request.db = db

        try:
            result = f(*args, **kwargs)
        finally:
            db.close()

        return result
    return decorated


@app.route('/api/documents', methods=['GET'])
@require_auth
def list_documents():
    user = request.current_user
    page = request.args.get('page', '1')
    per_page = request.args.get('per_page', '20')

    try:
        page_int = int(page)
        per_page_int = int(per_page)
    except ValueError:
        page_int = 1
        per_page_int = 20

    docs = doc_service.list_documents(
        request.db, user['id'], user['role'], page_int, per_page_int
    )
    return jsonify({'documents': docs})


@app.route('/api/documents/<int:doc_id>', methods=['GET'])
@require_auth
def get_document(doc_id):
    user = request.current_user
    doc, error = doc_service.get_document(
        request.db, user['id'], user['role'], doc_id
    )

    if error == "not_found":
        abort(404)
    elif error == "forbidden":
        abort(403)

    return jsonify({'document': doc})


if __name__ == '__main__':
    init_db()
    app.run(debug=False)
